  String an_uri = "";
  try { if (data != null && data.getData() != null) an_uri = data.getData().toString(); } catch (Exception e) {}
  com.Plugins.AndroidNative.DeviceInfo.nativeOnActivityResult(requestCode, resultCode, an_uri);
